void handle_sas_tasks() {
    struct command *cmd, *next;
    again:
    list_for_each_entry_safe(cmd, next, &work_q, list) {
        unsigned long flags;

        if (!cmd->needs_device_reset)
            continue;

        spin_lock_irqsave(&cmd->state_lock, flags);
        switch (cmd->state) {
        case CMD_STATE_COMPLETED:
            finish_command(cmd);
            break;
        case CMD_STATE_ABORTED:
            clear_command_queue(cmd);
            break;
        case CMD_STATE_AT_LU:
            if (recover_logical_unit(cmd)) {
                spin_unlock_irqrestore(&cmd->state_lock, flags);
                continue;
            }
            break;
        case CMD_STATE_I_T:
            if (recover_i_t_relationship(cmd)) {
                spin_unlock_irqrestore(&cmd->state_lock, flags);
                continue;
            }
            break;
        default:
            spin_unlock_irqrestore(&cmd->state_lock, flags);
            continue;
        }
        spin_unlock_irqrestore(&cmd->state_lock, flags);

        log_error("Failed to recover device for command");
    }
}

void handle_sas_tasks(void) {
    struct command *cmd;
    unsigned long flags;

    Again:
    while ((cmd = list_first_entry_or_null(&work_q, struct command, list))) {
        if (cmd->task->reset_requested) {
            spin_lock_irqsave(&cmd->task->state_lock, flags);
            switch (cmd->task->state) {
                case TASK_COMPLETED:
                    finish_command(cmd);
                    break;
                case TASK_ABORTED:
                    abort_command(cmd);
                    break;
                case TASK_AT_LU:
                    if (recover_lu(cmd->task))
                        continue;
                    else if (recover_i_t(cmd->task))
                        continue;
                    else {
                        log_error("Failed to recover device.");
                    }
                    break;
                default:
                    break;
            }
            spin_unlock_irqrestore(&cmd->task->state_lock, flags);
        }
    }

    return;
}

void handle_sas_tasks(void) {
    struct command *cmd, *tmp;

    Again:
    list_for_each_entry_safe(cmd, tmp, &work_q, list) {
        unsigned int reset_needed = 0;
        unsigned int state;

        spin_lock_irqsave(&cmd->task_state_lock);
        state = cmd->state;
        reset_needed = (cmd->flags & SAS_TASK_NEED_RESET);
        spin_unlock_irqrestore(&cmd->task_state_lock, flags);

        if (!reset_needed)
            continue;

        switch (state) {
            case SAS_TASK_STATE_DONE:
                finish_command(cmd);
                break;
            case SAS_TASK_STATE_ABORTED:
                clear_queues(cmd);
                break;
            case SAS_TASK_STATE_AT_LU:
                if (!recover_lu(cmd)) {
                    log_error("Failed to recover LU for device %s\n", cmd->device_name);
                    continue;
                }
                break;
            case SAS_TASK_STATE_I_T_NEXUS_LOST:
                if (!recover_i_t(cmd)) {
                    log_error("Failed to recover I_T for device %s\n", cmd->device_name);
                    continue;
                }
                break;
            default:
                log_error("Unknown task state %d for device %s\n", state, cmd->device_name);
                continue;
        }

        spin_lock_irqsave(&cmd->task_state_lock);
        cmd->flags &= ~SAS_TASK_NEED_RESET;
        spin_unlock_irqrestore(&cmd->task_state_lock, flags);
    }

    schedule_work(&work_q);
    goto Again;
}

void handle_sas_tasks(void) {
    struct command *cmd, *tmp;
    int recovered = 0;

    Again:
    list_for_each_entry_safe(cmd, tmp, &work_q, list) {
        unsigned int task_state;

        spin_lock_irq(&cmd->task_state_lock);
        task_state = cmd->task_state;
        spin_unlock_irq(&cmd->task_state_lock);

        if (task_state == SAS_TASK_NEED_RESET) {
            recovered = 0;

            if (cmd->device_reset_needed) {
                if (cmd->task_state == SAS_TASK_AT_LU) {
                    if (recover_logical_unit(cmd)) {
                        recovered = 1;
                    } else if (recover_i_t_relationship(cmd)) {
                        recovered = 1;
                    }
                }

                if (!recovered) {
                    spin_lock_irq(&cmd->task_state_lock);
                    cmd->task_state = SAS_TASK_FAILED;
                    spin_unlock_irq(&cmd->task_state_lock);
                    log_error("Failed to recover device for command.");
                    continue;
                }

                spin_lock_irq(&cmd->task_state_lock);
                cmd->task_state = SAS_TASK_COMPLETED;
                spin_unlock_irq(&cmd->task_state_lock);
                finish_command(cmd);
                clear_queues();
                goto Again;
            }

            if (task_state == SAS_TASK_ABORTED) {
                abort_command(cmd);
                continue;
            }

            if (task_state == SAS_TASK_COMPLETED) {
                finish_command(cmd);
                continue;
            }
        }
    }
}

void handle_sas_tasks_recovery(void) {
    struct command *cmd, *tmp;
    int reset_needed;

    again:
    list_for_each_entry_safe(cmd, tmp, &work_q, list) {
        reset_needed = 0;

        spin_lock_irq(&cmd->state_lock);
        if (cmd->state == SAS_TASK_NEED_RESET) {
            reset_needed = 1;
        }
        spin_unlock_irq(&cmd->state_lock);

        if (!reset_needed)
            continue;

        if (cmd->state == SAS_TASK_LU_RESET) {
            if (recover_lu(cmd)) {
                cmd->state = SAS_TASK_COMPLETED;
                finish_command(cmd);
            } else {
                log_error("LU recovery failed for device %s", cmd->device_id);
                cmd->state = SAS_TASK_FAILED;
            }
        } else if (cmd->state == SAS_TASK_I_T_RESET) {
            if (recover_i_t(cmd)) {
                cmd->state = SAS_TASK_COMPLETED;
                finish_command(cmd);
            } else {
                log_error("I_T recovery failed for device %s", cmd->device_id);
                cmd->state = SAS_TASK_FAILED;
            }
        } else if (cmd->state == SAS_TASK_ABORTED) {
            clear_command(cmd);
            continue;
        } else {
            log_error("Unknown task state for device %s", cmd->device_id);
            cmd->state = SAS_TASK_FAILED;
        }

        if (cmd->state == SAS_TASK_FAILED)
            clear_queues(cmd);
    }

    if (recovery_needed()) {
        goto again;
    }
}
